{
    bool bb;
    int offset = PixelOffset(i1, i2, bb);
    u8 *pixels = mPixels;
    if (mBpp == 8) {
        *(pixels + offset) = uc;
    } else if (bb) {
        u8 old = *(pixels + offset);
        *(pixels + offset) = (uc << 4) | (old & 0xF);
    } else {
        u8 old = *(pixels + offset);
        *(pixels + offset) = (old & 0xF0) | uc;
    }
}

{
    YUV444 *src;
    RGB *dst;
    int row;
    for (row = 0; row < height; row++) {
        src = source;
        dst = destination;
        for (int x = 0; x < width; x++) {
            int y = src->y - 16;
            int u = src->u - 128;
            int v = src->v - 128;
            int r = (1164 * y + 1596 * v + 500) / 1000;
            int g = (1164 * y - 813 * v - 391 * u + 500) / 1000;
            int b = (1164 * y + 2018 * u + 500) / 1000;
            dst->r = r > 255 ? 255 : (r < 0 ? 0 : r);
            dst->g = g > 255 ? 255 : (g < 0 ? 0 : g);
            dst->b = b > 255 ? 255 : (b < 0 ? 0 : b);
            src++;
            dst++;
        }
        source += width;
        destination += width;
    }
}

